<script setup>
import { computed, ref } from 'vue'
import { allowedStatuses, dateKey, money, number, statuses, sumResults } from '../data.js'
import { tr, t } from '../i18n.js'
import Icon from './Icon.vue'
const props=defineProps({state:Object,report:Object,days:Number})
const emit=defineEmits(['action','navigate'])
const threshold=ref(3),forecastBudget=ref(props.state.profile.budget)
const metrics=computed(()=>{
  const x=props.report.total
  return [{label:'CPC',value:x.clicks?money(x.spend/x.clicks,2):'—',note:tr('Xarajat / bosish','Расходы / клики','Spend / clicks')},{label:'CPM',value:x.impressions?money(x.spend/x.impressions*1000,2):'—',note:tr('Xarajat / 1000 ko‘rsatish','Расходы / 1000 показов','Spend / 1,000 impressions')},{label:'CPA',value:x.conversions?money(x.spend/x.conversions,2):'—',note:tr('Xarajat / konversiya','Расходы / конверсии','Spend / conversions')},{label:'CAC',value:x.customers?money(x.spend/x.customers,2):'—',note:tr('Reklama xarajati / yangi mijoz','Рекламные расходы / новые клиенты','Ad spend / new customers')}]
})
const campaigns=computed(()=>props.state.campaigns.map(item=>({...item,total:sumResults(item.results.filter(row=>row.date>=dateKey(1-props.days)&&row.date<=dateKey()))})))
const weak=computed(()=>campaigns.value.filter(item=>item.status==='active'&&item.total.leads>0&&item.total.spend/item.total.leads>threshold.value))
const totalBudget=computed(()=>props.state.campaigns.filter(item=>item.status==='active').reduce((sum,item)=>sum+Number(item.budget)*30,0))
const forecast=computed(()=>props.report.total.spend>0&&props.report.total.leads>0?Math.floor(Number(forecastBudget.value)/(props.report.total.spend/props.report.total.leads)):null)
const attributed=computed(()=>props.state.campaigns.map(campaign=>{const leads=props.state.leads.filter(lead=>lead.campaignId===campaign.id);const won=leads.filter(lead=>lead.status==='won');return {campaign,leads:leads.length,won:won.length,value:won.reduce((sum,lead)=>sum+(Number(lead.value)||0),0)}}))
const products=computed(()=>Object.values(campaigns.value.reduce((map,campaign)=>{const key=campaign.product||tr('Belgilanmagan','Не указано','Unassigned');const row=map[key]||{product:key,leads:0,spend:0,revenue:0};for(const metric of ['leads','spend','revenue'])row[metric]+=campaign.total[metric];map[key]=row;return map},{})))
const validThreshold=computed(()=>Number.isFinite(threshold.value)&&threshold.value>=0)
</script>
<template>
  <section class="glass detail-card"><div class="section-head"><div><h2>{{tr('Chuqurroq o‘lchovlar','Дополнительные показатели','Deeper measurement')}}</h2><p>{{tr('Kunlik kampaniya natijalaridan hisoblanadi. Ma’lumot bo‘lmasa — ko‘rsatiladi.','Рассчитываются из дневных результатов. При отсутствии данных отображается —.','Calculated from daily campaign results. Missing data is shown as —.')}}</p></div><Icon name="activity" :size="21"/></div><div class="insight-grid"><div v-for="metric in metrics" :key="metric.label" class="insight-metric"><small>{{metric.label}}</small><strong>{{metric.value}}</strong><p>{{metric.note}}</p></div></div></section>
  <div class="dashboard-grid"><section class="glass detail-card"><div class="section-head"><div><h2>{{tr('Budjet va prognoz','Бюджет и прогноз','Budget and forecast')}}</h2><p>{{tr('CPL o‘zgarmaydi degan taxmin asosida.','При условии неизменного CPL.','Assumes the current CPL remains unchanged.')}}</p></div></div><div class="form-grid"><label class="field"><span>{{tr('Rejalashtirilgan xarajat ($)','Планируемые расходы ($)','Planned spend ($)')}}</span><input v-model.number="forecastBudget" type="number" min="0" max="30000000"/></label><div class="insight-metric"><small>{{tr('Taxminiy leadlar','Ожидаемые лиды','Estimated leads')}}</small><strong>{{forecast!==null&&forecastBudget>=0?number(forecast):'—'}}</strong></div></div><p class="detail-note">{{tr('Faol kampaniyalarning 30 kunlik budjeti','30-дневный бюджет активных кампаний','Active campaigns: 30-day budget')}}: {{money(totalBudget,2)}} / {{money(state.profile.budget,2)}}.<span v-if="totalBudget>state.profile.budget"> {{tr('Profil budjeti oshib ketgan.','Бюджет профиля превышен.','Exceeds the profile budget.')}}</span></p></section><section class="glass detail-card"><div class="section-head"><div><h2>{{tr('CRM holatlari','Статусы CRM','CRM stages')}}</h2><p>{{tr('Joriy holat bo‘yicha taqsimot.','Распределение по текущему статусу.','Distribution by current status.')}}</p></div></div><div v-for="stage in allowedStatuses.leads" :key="stage" class="funnel-row"><span>{{t(statuses[stage].label)}}</span><div class="funnel-track"><i :style="{width:(state.leads.length?state.leads.filter(lead=>lead.status===stage).length/state.leads.length*100:0)+'%'}"></i></div><strong>{{state.leads.filter(lead=>lead.status===stage).length}}</strong></div></section></div>
  <section class="glass detail-card insight-actions"><div class="section-head"><div><h2>{{tr('Optimallashtirish navbati','Очередь оптимизации','Optimization queue')}}</h2><p>{{tr('CPL chegaradan oshgan kampaniyalarni ko‘rib chiqing.','Проверьте кампании, превышающие порог CPL.','Review campaigns that exceed your CPL threshold.')}}</p></div><label class="field"><span>{{tr('CPL chegarasi ($)','Порог CPL ($)','CPL limit ($)')}}</span><input v-model.number="threshold" type="number" min="0" max="1000000" step="0.01"/></label></div><article v-for="campaign in validThreshold?weak:[]" :key="campaign.id" class="recommendation"><span class="icon-tile tone-amber"><Icon name="info" :size="19"/></span><div><strong>{{campaign.title}}</strong><p>CPL {{money(campaign.total.spend/campaign.total.leads,2)}} · {{campaign.total.leads}} {{tr('lead. Avval sifatini va namunani tekshiring.','лидов. Сначала проверьте качество и выборку.','leads. Review lead quality and sample size first.')}}</p></div><button class="button button-secondary button-compact" @click="emit('action',{action:'recommend-pause',id:campaign.id,payload:{threshold,days}})">{{tr('Pauzani tasdiqqa yuborish','На согласование паузы','Request pause approval')}}</button></article><p v-if="!weak.length" class="subtle">{{tr('Tanlangan chegaradan oshgan faol kampaniya yo‘q.','Нет активных кампаний выше выбранного порога.','No active campaigns exceed this threshold.')}}</p><button class="approval-link" @click="emit('navigate','automation')">{{tr('Tasdiqlarni ko‘rish','Посмотреть согласования','Review approvals')}}<Icon name="arrowRight" :size="16"/></button></section>
  <section class="glass detail-card"><div class="section-head"><div><h2>{{tr('Sotuvga bog‘lanish','Связь с продажами','Sales attribution')}}</h2><p>{{tr('CRMga bog‘langan leadlar va qo‘lda kiritilgan bitim qiymati; barcha davrlar.','Лиды CRM и введённая стоимость сделок; за всё время.','Linked CRM leads and manually entered deal values; all time.')}}</p></div></div><div class="table-scroll"><table><thead><tr><th>{{tr('Kampaniya','Кампания','Campaign')}}</th><th>{{tr('Leadlar','Лиды','Leads')}}</th><th>{{tr('Sotuvlar','Продажи','Sales')}}</th><th>{{tr('Bitim qiymati','Стоимость сделок','Deal value')}}</th></tr></thead><tbody><tr v-for="row in attributed" :key="row.campaign.id"><td>{{row.campaign.title}}</td><td>{{row.leads}}</td><td>{{row.won}}</td><td>{{money(row.value,2)}}</td></tr></tbody></table></div></section>
  <section class="glass detail-card"><div class="section-head"><div><h2>{{tr('Mahsulot bo‘yicha','По продуктам','By product')}}</h2><p>{{tr('Kampaniya tahririda mahsulot nomini belgilang.','Укажите продукт в настройках кампании.','Assign a product in the campaign editor.')}}</p></div></div><div class="table-scroll"><table><thead><tr><th>{{tr('Mahsulot','Продукт','Product')}}</th><th>{{tr('Leadlar','Лиды','Leads')}}</th><th>{{tr('Xarajat','Расходы','Spend')}}</th><th>{{tr('Daromad','Доход','Revenue')}}</th></tr></thead><tbody><tr v-for="row in products" :key="row.product"><td>{{row.product}}</td><td>{{number(row.leads)}}</td><td>{{money(row.spend,2)}}</td><td>{{money(row.revenue,2)}}</td></tr></tbody></table></div></section>
</template>
